// The other languages: loaded when chosen. A key missing in one of them is shown in English.
const LOADERS = {
  da: () => import('./i18n/da.js'),
  de: () => import('./i18n/de.js'),
  hi: () => import('./i18n/hi.js'),
  sv: () => import('./i18n/sv.js'),
  nb: () => import('./i18n/nb.js'),
  nl: () => import('./i18n/nl.js'),
  fr: () => import('./i18n/fr.js'),
  es: () => import('./i18n/es.js'),
};
const LOCALES = {
  en: 'en-GB', da: 'da-DK', de: 'de-DE', hi: 'hi-IN', sv: 'sv-SE', nb: 'nb-NO', nl: 'nl-NL', fr: 'fr-FR', es: 'es-ES',
};
// browser languages read as one of ours: Norwegian (no) and nynorsk (nn) get bokmål
const ALIASES = { no: 'nb', nn: 'nb' };
const DICTS = { en };
const STORE_KEY = 'onlineifc.lang';

/** Loads the texts of a language, once. False when it cannot be loaded (offline before it was ever used). */
async function load(l) {
  if (DICTS[l]) return true;
  if (!LOADERS[l]) return false;
  try {
    DICTS[l] = (await LOADERS[l]()).default;
    return true;
  } catch (e) {
    console.warn(`Language ${l} could not be loaded`, e);
    return false;
  }
}

let lang = 'en';
let wanted = 'en';
try {
  const saved = localStorage.getItem(STORE_KEY);
  if (saved && LOCALES[saved]) wanted = saved;
  else {
    // first visit: the language of the browser, when we have it
    for (const l of navigator.languages || [navigator.language || '']) {
      const two = String(l).slice(0, 2).toLowerCase();
      const code = ALIASES[two] || two;
      if (LOCALES[code]) { wanted = code; break; }
    }
  }
} catch { /* ignore */ }
// the language the app starts in, before any text is made (the modules importing this wait for it)
if (await load(wanted)) lang = wanted;

export function getLang() { return lang; }

/** Switches the language (loading it first). Resolves to false, keeping the current one, when it cannot be loaded. */
export async function setLang(l) {
  if (!(await load(l))) return false;
  lang = l;
  try { localStorage.setItem(STORE_KEY, l); } catch { /* ignore */ }
  document.documentElement.lang = l;
  return true;
}

/** Translates a key. Falls back to English, then to the key itself. */
export function t(key, vars = {}) {
  const v = DICTS[lang][key] ?? en[key];
  if (v === undefined) return key;
  if (typeof v === 'function') return v(vars);
  return v.replace(/\{(\w+)\}/g, (_, k) => (vars[k] !== undefined ? String(vars[k]) : `{${k}}`));
}

export function fmtNum(n) {
  return Number(n).toLocaleString(LOCALES[lang]);
}

/** The decimal sign of the language: ',' for Danish, German, Swedish, Norwegian, Dutch, French and Spanish. */
export function decimalSign() {
  return (1.5).toLocaleString(LOCALES[lang]).includes(',') ? ',' : '.';
}

/** Translates static HTML marked with data-i18n, data-i18n-title, data-i18n-placeholder and data-i18n-html. */
export function applyStaticTranslations(root = document) {
  document.documentElement.lang = lang;
  for (const el of root.querySelectorAll('[data-i18n]')) el.textContent = t(el.dataset.i18n);
  for (const el of root.querySelectorAll('[data-i18n-html]')) el.innerHTML = t(el.dataset.i18nHtml);
  for (const el of root.querySelectorAll('[data-i18n-title]')) el.title = t(el.dataset.i18nTitle);
  for (const el of root.querySelectorAll('[data-i18n-placeholder]')) el.placeholder = t(el.dataset.i18nPlaceholder);
}

export const LANGUAGES = Object.keys(LOCALES);
export const _dicts = DICTS; // for tests: the languages loaded so far
